3	/**
4	 * Contains "command" code for "one-and-dones"--options passed
5	 * to Mocha which cause it to just dump some info and exit.
6	 * See {@link module:lib/cli/one-and-dones.ONE_AND_DONE_ARGS ONE_AND_DONE_ARGS} for more info.
7	 * @module
8	 * @private
9	 */
10	
11	const Mocha = require('../mocha');
12	
13	/**
14	 * Dumps a sorted list of the enumerable, lower-case keys of some object
15	 * to `STDOUT`.
16	 * @param {Object} obj - Object, ostensibly having some enumerable keys
17	 * @ignore
18	 * @private
19	 */
20	const showKeys = obj => {
21	  console.log();
22	  const keys = Object.keys(obj);
23	  const maxKeyLength = keys.reduce((max, key) => Math.max(max, key.length), 0);
24	  keys
25	    .filter(
26	      key => /^[a-z]/.test(key) && !obj[key].browserOnly && !obj[key].abstract
27	    )
28	    .sort()
29	    .forEach(key => {
30	      const description = obj[key].description;
31	      console.log(
32	        `    ${key.padEnd(maxKeyLength + 1)}${
33	          description ? `- ${description}` : ''
34	        }`
35	      );
36	    });
37	  console.log();
38	};
