40	/**
41	 * Handlers for one-and-done options
42	 * @namespace
43	 * @private
44	 */
45	exports.ONE_AND_DONES = {
46	  /**
47	   * Dump list of built-in interfaces
48	   * @private
49	   */
50	  'list-interfaces': () => {
51	    showKeys(Mocha.interfaces);
52	  },
53	  /**
54	   * Dump list of built-in reporters
55	   * @private
56	   */
57	  'list-reporters': () => {
58	    showKeys(Mocha.reporters);
59	  }
60	};
61	
62	/**
63	 * A Set of all one-and-done options
64	 * @type Set<string>
65	 * @private
66	 */
67	exports.ONE_AND_DONE_ARGS = new Set(
68	  ['help', 'h', 'version', 'V'].concat(Object.keys(exports.ONE_AND_DONES))
69	);
